// Local build only: Git read and deterministic static assets, no external calls.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../../', import.meta.url);
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const commit = process.argv[2];
if (!/^[a-f0-9]{40}$/.test(commit ?? '')) throw Error('Pass an explicit reviewed source commit SHA');
const repositoryPath = 'packages/maverick/scripts/seed-data.json';
const seed = JSON.parse(git('show', `${commit}:${repositoryPath}`));
const raw = seed.find(x => x.key === 'content:home')?.value;
if (typeof raw !== 'string' || raw.length > 32768 || typeof JSON.parse(raw).hero?.title !== 'string') throw Error('Invalid source seed');
const assets = {};
for (const [path, file, contentType] of [
  ['/collaboration/', 'hosted/public/index.html', 'text/html; charset=utf-8'],
  ['/collaboration/app.js', 'hosted/public/app.js', 'text/javascript; charset=utf-8'],
  ['/collaboration/style.css', 'hosted/public/style.css', 'text/css; charset=utf-8'],
  ['/collaboration/canon.css', '../../packages/canon/src/lib/styles/tokens.css', 'text/css; charset=utf-8'],
]) assets[path] = { body: readFileSync(new URL(file, import.meta.url), 'utf8'), contentType };
writeFileSync(new URL('hosted/worker-bundle.ts', import.meta.url), '// Generated by prepare-worker-bundle.mjs from the explicit reviewed source SHA.\nexport const sourceBundle = ' + JSON.stringify({ commit, raw, repositoryPath }) + ';\nexport const workerAssets = ' + JSON.stringify(assets) + ';\n');
